from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test-order")
async def test_order(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_file_after_form():
    # This is the case that is reported to fail
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/test-order", data=data, files=files)
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

def test_form_after_file():
    # This is the case that is reported to work
    # But we need a different endpoint for this
    pass

@app.post("/test-order-reversed")
async def test_order_reversed(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

def test_form_after_file_reversed():
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/test-order-reversed", data=data, files=files)
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_file_after_form()
        print("test_file_after_form passed")
    except Exception as e:
        print(f"test_file_after_form failed: {e}")

    try:
        test_form_after_file_reversed()
        print("test_form_after_file_reversed passed")
    except Exception as e:
        print(f"test_form_after_file_reversed failed: {e}")

