import asyncio
from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test_form_file")
async def test_form_file(form_val: str = Form(...), file_val: bytes = File(...)):
    return {"form_val": form_val, "file_val": file_val}

@app.post("/test_file_form")
async def test_file_form(file_val: bytes = File(...), form_val: str = Form(...)):
    return {"form_val": form_val, "file_val": file_val}

@app.post("/test_uploadfile")
async def test_uploadfile(form_val: str = Form(...), file_val: UploadFile = File(...)):
    return {"form_val": form_val, "file_val": file_val.filename}

client = TestClient(app)

def test_form_then_file_bytes():
    # This is the case that was failing
    response = client.post(
        "/test_form_file",
        data={"form_val": "hello"},
        files={"file_val": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": b"world".hex()} # FastAPI might return bytes as hex or string depending on version, but let's check if it's 200

def test_file_then_form_bytes():
    # This case should have been working
    response = client.post(
        "/test_file_form",
        data={"form_val": "hello"},
        files={"file_val": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": b"world".hex()}

def test_uploadfile_not_read():
    # This case should ensure we don't accidentally read UploadFile
    response = client.post(
        "/test_uploadfile",
        data={"form_val": "hello"},
        files={"file_val": ("test.txt", b"world")}
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "test.txt"}

if __name__ == "__main__":
    # Run tests manually if not using pytest
    try:
        test_form_then_file_bytes()
        print("test_form_then_file_bytes passed")
        test_file_then_form_bytes()
        print("test_file_then_form_bytes passed")
        test_uploadfile_not_read()
        print("test_uploadfile_not_read passed")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e

